"""Versioned HTTP routes (``/v1``)."""

from __future__ import annotations

import base64
import re
from typing import Annotated, Literal

from fastapi import APIRouter, Depends, Query, Request, Response, status
from sqlalchemy.orm import Session

from provenance import service
from provenance.errors import LineageValidationError
from provenance.schemas import (
    ActorCreate,
    ActorResponse,
    AttestationCreate,
    AttestationListResponse,
    AttestationResponse,
    ClaimCreate,
    ClaimListResponse,
    ClaimResponse,
    ContentCreate,
    ContentLineageItem,
    ContentLineageResponse,
    ContentListResponse,
    ContentRelationCreate,
    ContentRelationListResponse,
    ContentRelationResponse,
    ContentResponse,
    EvidenceBundleCreate,
    EvidenceBundleListResponse,
    EvidenceBundleResponse,
)

router = APIRouter(prefix="/v1")


def get_db(request: Request) -> Session:
    """Yield a session from the factory bound to the application."""
    factory = request.app.state.session_factory
    session = factory()
    try:
        yield session
    finally:
        session.close()


DbSession = Annotated[Session, Depends(get_db)]


@router.post("/actors", response_model=ActorResponse, status_code=status.HTTP_201_CREATED)
def create_actor(payload: ActorCreate, session: DbSession) -> ActorResponse:
    actor = service.create_actor(session, payload)
    return ActorResponse.model_validate(actor)


@router.post("/contents", response_model=ContentResponse)
def create_content(
    payload: ContentCreate, session: DbSession, response: Response
) -> ContentResponse:
    content, created = service.create_content(session, payload)
    # First registration -> 201; an idempotent repeat submission -> 200, and
    # the existing resource is returned unchanged.
    response.status_code = (
        status.HTTP_201_CREATED if created else status.HTTP_200_OK
    )
    return ContentResponse.model_validate(content)


@router.get("/contents/{content_id}", response_model=ContentResponse)
def get_content(content_id: str, session: DbSession) -> ContentResponse:
    content = service.get_content(session, content_id)
    return ContentResponse.model_validate(content)


@router.get("/contents", response_model=ContentListResponse)
def list_contents(
    session: DbSession, actor_id: str | None = None
) -> ContentListResponse:
    items = service.list_contents(session, actor_id)
    return ContentListResponse(
        items=[ContentResponse.model_validate(item) for item in items],
        count=len(items),
    )


@router.post("/content-relations", response_model=ContentRelationResponse)
def create_content_relation(
    payload: ContentRelationCreate, session: DbSession, response: Response
) -> ContentRelationResponse:
    relation, created = service.create_content_relation(session, payload)
    # First creation -> 201; an idempotent repeat submission -> 200, and the
    # existing immutable relation is returned unchanged.
    response.status_code = (
        status.HTTP_201_CREATED if created else status.HTTP_200_OK
    )
    return ContentRelationResponse.model_validate(relation)


@router.get(
    "/content-relations/{relation_id}",
    response_model=ContentRelationResponse,
)
def get_content_relation(
    relation_id: str, session: DbSession
) -> ContentRelationResponse:
    relation = service.get_content_relation(session, relation_id)
    return ContentRelationResponse.model_validate(relation)


@router.get(
    "/contents/{content_id}/relations",
    response_model=ContentRelationListResponse,
)
def list_content_relations(
    content_id: str, session: DbSession
) -> ContentRelationListResponse:
    items = service.list_content_relations(session, content_id)
    return ContentRelationListResponse(
        items=[ContentRelationResponse.model_validate(item) for item in items],
        count=len(items),
    )


def _lineage_item(content, depth: int):
    # The full public content view, with the traversal depth added.
    fields = ContentResponse.model_validate(content).model_dump()
    return ContentLineageItem(**fields, depth=depth)


_INTEGER_RE = re.compile(r"-?[0-9]+")


def _lineage_query_error(field: str, msg: str, error_type: str):
    return LineageValidationError(
        [{"loc": ["query", field], "msg": msg, "type": error_type}]
    )


@router.get(
    "/contents/{content_id}/lineage",
    response_model=ContentLineageResponse,
)
def get_content_lineage(
    content_id: str,
    request: Request,
    session: DbSession,
    direction: str | None = Query(default=None),
    max_depth: str | None = Query(default=None),
) -> ContentLineageResponse:
    # Raw multi-values are inspected deliberately: FastAPI otherwise keeps
    # only the last value of a repeated scalar parameter and Pydantic coerces
    # "8.0" to 8, both of which must be rejected rather than silently
    # defaulted or normalized.
    raw = request.query_params
    for field in ("direction", "max_depth"):
        if len(raw.getlist(field)) > 1:
            raise _lineage_query_error(
                field,
                f"query parameter {field} must be provided exactly once",
                "value_error.repeated",
            )

    if direction is None:
        raise _lineage_query_error(
            "direction", "Field required", "value_error.missing"
        )
    if direction not in service.LINEAGE_DIRECTIONS:
        # Covers missing values, whitespace/blank strings, and any value
        # other than the two literal traversal directions.
        raise _lineage_query_error(
            "direction",
            "direction must be 'ancestors' or 'descendants'",
            "value_error",
        )

    if max_depth is None:
        depth = service.DEFAULT_LINEAGE_MAX_DEPTH
    else:
        if not _INTEGER_RE.fullmatch(max_depth):
            raise _lineage_query_error(
                "max_depth",
                "max_depth must be an integer",
                "value_error.integer",
            )
        depth = int(max_depth)
        if not (
            service.MIN_LINEAGE_MAX_DEPTH
            <= depth
            <= service.MAX_LINEAGE_MAX_DEPTH
        ):
            raise _lineage_query_error(
                "max_depth",
                "max_depth must be between 1 and 32",
                "value_error.range",
            )

    items = service.get_content_lineage(session, content_id, direction, depth)
    return ContentLineageResponse(
        items=[_lineage_item(content, d) for content, d in items],
        count=len(items),
    )


@router.post("/claims", response_model=ClaimResponse)
def create_claim(
    payload: ClaimCreate, session: DbSession, response: Response
) -> ClaimResponse:
    claim, created = service.create_claim(session, payload)
    # First creation -> 201; an idempotent repeat submission -> 200, and the
    # existing immutable claim is returned unchanged.
    response.status_code = (
        status.HTTP_201_CREATED if created else status.HTTP_200_OK
    )
    return ClaimResponse.model_validate(claim)


@router.get("/claims/{claim_id}", response_model=ClaimResponse)
def get_claim(claim_id: str, session: DbSession) -> ClaimResponse:
    claim = service.get_claim(session, claim_id)
    return ClaimResponse.model_validate(claim)


@router.get("/contents/{content_id}/claims", response_model=ClaimListResponse)
def list_content_claims(content_id: str, session: DbSession) -> ClaimListResponse:
    items = service.list_claims_for_content(session, content_id)
    return ClaimListResponse(
        items=[ClaimResponse.model_validate(item) for item in items],
        count=len(items),
    )


def _bundle_response(bundle) -> EvidenceBundleResponse:
    # Map the ORM's reserved-name-safe ``metadata_`` attribute to the
    # wire-level ``metadata`` object explicitly.
    return EvidenceBundleResponse(
        id=bundle.id,
        claim_id=bundle.claim_id,
        evidence_type=bundle.evidence_type,
        digest_algorithm=bundle.digest_algorithm,
        digest_hex=bundle.digest_hex,
        media_type=bundle.media_type,
        metadata=bundle.metadata_,
        created_at=bundle.created_at,
    )


@router.post("/evidence-bundles", response_model=EvidenceBundleResponse)
def create_evidence_bundle(
    payload: EvidenceBundleCreate, session: DbSession, response: Response
) -> EvidenceBundleResponse:
    bundle, created = service.create_evidence_bundle(session, payload)
    # First creation -> 201; an idempotent repeat submission -> 200, and the
    # existing bundle (with its original metadata) is returned unchanged.
    response.status_code = (
        status.HTTP_201_CREATED if created else status.HTTP_200_OK
    )
    return _bundle_response(bundle)


@router.get(
    "/evidence-bundles/{evidence_bundle_id}",
    response_model=EvidenceBundleResponse,
)
def get_evidence_bundle(
    evidence_bundle_id: str, session: DbSession
) -> EvidenceBundleResponse:
    bundle = service.get_evidence_bundle(session, evidence_bundle_id)
    return _bundle_response(bundle)


@router.get(
    "/claims/{claim_id}/evidence-bundles",
    response_model=EvidenceBundleListResponse,
)
def list_claim_evidence_bundles(
    claim_id: str, session: DbSession
) -> EvidenceBundleListResponse:
    items = service.list_evidence_bundles_for_claim(session, claim_id)
    return EvidenceBundleListResponse(
        items=[_bundle_response(item) for item in items],
        count=len(items),
    )


def _attestation_response(attestation) -> AttestationResponse:
    # The raw signature is never available here: only the stored public key
    # bytes and signature digest leave the service.
    return AttestationResponse(
        id=attestation.id,
        target_type=attestation.target_type,
        target_id=attestation.target_id,
        signer_actor_id=attestation.signer_actor_id,
        public_key=base64.b64encode(attestation.public_key).decode("ascii"),
        signature_digest_algorithm=attestation.signature_digest_algorithm,
        signature_digest_hex=attestation.signature_digest_hex,
        verified=True,
        created_at=attestation.created_at,
    )


@router.post("/attestations", response_model=AttestationResponse)
def create_attestation(
    payload: AttestationCreate, session: DbSession, response: Response
) -> AttestationResponse:
    attestation, created = service.create_attestation(session, payload)
    # First creation -> 201; an idempotent repeat submission -> 200, and the
    # existing attestation is returned unchanged.
    response.status_code = (
        status.HTTP_201_CREATED if created else status.HTTP_200_OK
    )
    return _attestation_response(attestation)


@router.get(
    "/attestations/{attestation_id}",
    response_model=AttestationResponse,
)
def get_attestation(
    attestation_id: str, session: DbSession
) -> AttestationResponse:
    attestation = service.get_attestation(session, attestation_id)
    return _attestation_response(attestation)


@router.get("/attestations", response_model=AttestationListResponse)
def list_attestations(
    session: DbSession,
    target_type: Literal["claim", "evidence_bundle"] | None = None,
    target_id: str | None = None,
) -> AttestationListResponse:
    items = service.list_attestations(session, target_type, target_id)
    return AttestationListResponse(
        items=[_attestation_response(item) for item in items],
        count=len(items),
    )

"""Request and response schemas for the versioned JSON API.

There is deliberately no field capable of carrying content bytes: only digest
and metadata are accepted, so raw content cannot be persisted or logged.
"""

from __future__ import annotations

import base64
import binascii
import re
from datetime import datetime
from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field, field_validator

from provenance.canonical import canonical_json_bytes
from provenance.ed25519 import PUBLIC_KEY_LENGTH, SIGNATURE_LENGTH
from provenance.models import SUPPORTED_DIGEST_ALGORITHMS

_HEX64 = re.compile(r"^[0-9a-f]{64}$")


def _required_nonempty(value: str, field: str) -> str:
    cleaned = value.strip()
    if not cleaned:
        raise ValueError(f"{field} must not be empty")
    return cleaned


def _decode_base64(value: Any, field: str, expected_length: int) -> bytes:
    """Strictly decode standard Base64 (RFC 4648) and enforce a byte length.

    The URL/filename-safe alphabet, missing/incorrect padding, non-string
    input, and any decoded length other than ``expected_length`` are
    rejected.
    """
    if not isinstance(value, str):
        raise ValueError(f"{field} must be a Base64-encoded string")
    try:
        # validate=True rejects non-alphabet characters (including '-'/'_')
        # and bad padding; then re-encoding enforces canonical padding.
        raw = base64.b64decode(value, validate=True)
    except (binascii.Error, ValueError):
        raise ValueError(
            f"{field} must be standard Base64 (RFC 4648) with correct padding"
        ) from None
    if base64.b64encode(raw).decode("ascii") != value:
        raise ValueError(f"{field} must use canonical standard Base64 padding")
    if len(raw) != expected_length:
        raise ValueError(
            f"{field} must decode to exactly {expected_length} bytes"
            f" (got {len(raw)})"
        )
    return raw


class ActorCreate(BaseModel):
    id: str = Field(..., min_length=1, max_length=255)
    name: str = Field(..., min_length=1, max_length=4096)
    type: str = Field(..., min_length=1, max_length=64)

    @field_validator("id")
    @classmethod
    def _id_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "id")

    @field_validator("name")
    @classmethod
    def _name_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "name")

    @field_validator("type")
    @classmethod
    def _type_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "type")


class ActorResponse(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: str
    name: str
    type: str
    created_at: datetime


class ContentCreate(BaseModel):
    digest_algorithm: str = Field(..., min_length=1, max_length=32)
    digest_hex: str = Field(..., min_length=1, max_length=128)
    media_type: str = Field(..., min_length=1, max_length=255)
    title: str | None = Field(default=None, max_length=4096)
    actor_id: str = Field(..., min_length=1, max_length=255)

    @field_validator("digest_algorithm")
    @classmethod
    def _algorithm_supported(cls, v: str) -> str:
        normalized = v.strip().lower()
        if normalized not in SUPPORTED_DIGEST_ALGORITHMS:
            supported = ", ".join(sorted(SUPPORTED_DIGEST_ALGORITHMS))
            raise ValueError(f"unsupported digest algorithm; supported: {supported}")
        return normalized

    @field_validator("digest_hex")
    @classmethod
    def _digest_is_sha256_hex(cls, v: str) -> str:
        # Normalize case so the same digest cannot be registered twice via
        # different casing; then enforce exactly 64 lowercase hex chars.
        normalized = v.strip().lower()
        if not _HEX64.fullmatch(normalized):
            raise ValueError("digest_hex must be exactly 64 hexadecimal characters")
        return normalized

    @field_validator("media_type")
    @classmethod
    def _media_type_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "media_type")

    @field_validator("actor_id")
    @classmethod
    def _actor_id_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "actor_id")

    @field_validator("title")
    @classmethod
    def _title_optional(cls, v: str | None) -> str | None:
        if v is None:
            return None
        cleaned = v.strip()
        return cleaned or None


class ContentResponse(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: str
    digest_algorithm: str
    digest_hex: str
    media_type: str
    title: str | None
    actor_id: str
    created_at: datetime


class ContentListResponse(BaseModel):
    items: list[ContentResponse]
    count: int


class ContentLineageItem(ContentResponse):
    """A content reached by lineage traversal: the full public view plus depth.

    ``depth`` is the shortest number of lineage edges from the traversal
    origin; the origin itself is never included.
    """

    depth: int


class ContentLineageResponse(BaseModel):
    items: list[ContentLineageItem]
    count: int


class ClaimCreate(BaseModel):
    content_id: str = Field(..., min_length=1, max_length=80)
    actor_id: str = Field(..., min_length=1, max_length=255)
    claim_type: str = Field(..., min_length=1, max_length=128)
    #: Must be a JSON object; arrays, scalars, and null are rejected.
    payload: dict[str, Any]

    @field_validator("content_id")
    @classmethod
    def _content_id_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "content_id")

    @field_validator("actor_id")
    @classmethod
    def _actor_id_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "actor_id")

    @field_validator("claim_type")
    @classmethod
    def _claim_type_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "claim_type")

    @field_validator("payload")
    @classmethod
    def _payload_canonicalizable(cls, v: dict[str, Any]) -> dict[str, Any]:
        try:
            canonical_json_bytes(v)
        except (TypeError, ValueError):
            # Non-finite numbers (NaN/Infinity) have no canonical JSON form.
            raise ValueError(
                "payload must be a JSON object with finite numbers"
            ) from None
        return v


class ClaimResponse(BaseModel):
    """Public claim view: associations, digest, and timestamps — no payload."""

    model_config = ConfigDict(from_attributes=True)

    id: str
    content_id: str
    actor_id: str
    claim_type: str
    payload_digest_algorithm: str
    payload_digest_hex: str
    created_at: datetime


class ClaimListResponse(BaseModel):
    items: list[ClaimResponse]
    count: int


class EvidenceBundleCreate(BaseModel):
    # Evidence bytes must never reach the service: any field not declared
    # here (e.g. "data" or "evidence") is a client error, not silently
    # dropped, so raw-byte smuggling is rejected at the boundary.
    model_config = ConfigDict(extra="forbid")

    claim_id: str = Field(..., min_length=1, max_length=80)
    evidence_type: str = Field(..., min_length=1, max_length=128)
    digest_algorithm: str = Field(..., min_length=1, max_length=32)
    digest_hex: str = Field(..., min_length=1, max_length=128)
    media_type: str = Field(..., min_length=1, max_length=255)
    #: Must be a JSON object; arrays, scalars, and null are rejected.
    metadata: dict[str, Any]

    @field_validator("claim_id")
    @classmethod
    def _claim_id_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "claim_id")

    @field_validator("evidence_type")
    @classmethod
    def _evidence_type_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "evidence_type")

    @field_validator("digest_algorithm")
    @classmethod
    def _algorithm_supported(cls, v: str) -> str:
        normalized = v.strip().lower()
        if normalized not in SUPPORTED_DIGEST_ALGORITHMS:
            supported = ", ".join(sorted(SUPPORTED_DIGEST_ALGORITHMS))
            raise ValueError(f"unsupported digest algorithm; supported: {supported}")
        return normalized

    @field_validator("digest_hex")
    @classmethod
    def _digest_is_sha256_hex(cls, v: str) -> str:
        # Normalize case so the same digest cannot create two bundles via
        # different casing; then enforce exactly 64 lowercase hex chars.
        normalized = v.strip().lower()
        if not _HEX64.fullmatch(normalized):
            raise ValueError("digest_hex must be exactly 64 hexadecimal characters")
        return normalized

    @field_validator("media_type")
    @classmethod
    def _media_type_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "media_type")

    @field_validator("metadata")
    @classmethod
    def _metadata_json_object(cls, v: dict[str, Any]) -> dict[str, Any]:
        try:
            canonical_json_bytes(v)
        except (TypeError, ValueError):
            # Non-finite numbers (NaN/Infinity) have no valid JSON form.
            raise ValueError(
                "metadata must be a JSON object with finite values"
            ) from None
        return v


class EvidenceBundleResponse(BaseModel):
    """Public evidence bundle view: associations, digest, metadata, time."""

    id: str
    claim_id: str
    evidence_type: str
    digest_algorithm: str
    digest_hex: str
    media_type: str
    metadata: dict[str, Any]
    created_at: datetime


class EvidenceBundleListResponse(BaseModel):
    items: list[EvidenceBundleResponse]
    count: int


class ContentRelationCreate(BaseModel):
    content_id: str = Field(..., min_length=1, max_length=80)
    parent_content_id: str = Field(..., min_length=1, max_length=80)
    #: "version_of" (a new version of the source) or "derived_from" (derived
    #: from the source); any other type is a validation error.
    relation_type: Literal["version_of", "derived_from"]

    @field_validator("content_id")
    @classmethod
    def _content_id_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "content_id")

    @field_validator("parent_content_id")
    @classmethod
    def _parent_content_id_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "parent_content_id")


class ContentRelationResponse(BaseModel):
    """Public relation view: the two endpoints, the type, and the timestamp."""

    model_config = ConfigDict(from_attributes=True)

    id: str
    content_id: str
    parent_content_id: str
    relation_type: Literal["version_of", "derived_from"]
    created_at: datetime


class ContentRelationListResponse(BaseModel):
    items: list[ContentRelationResponse]
    count: int


class AttestationCreate(BaseModel):
    # Attestation requests carry exactly the declared verification material;
    # undeclared fields are rejected rather than silently discarded.
    model_config = ConfigDict(extra="forbid")

    #: Polymorphic target: an existing claim or evidence bundle.
    target_type: Literal["claim", "evidence_bundle"]
    target_id: str = Field(..., min_length=1, max_length=80)
    #: An already-registered actor making the attestation.
    signer_actor_id: str = Field(..., min_length=1, max_length=255)
    #: Base64 Ed25519 public key; must decode to exactly 32 bytes.
    public_key: bytes
    #: Base64 Ed25519 signature; must decode to exactly 64 bytes. The raw
    #: signature is verified and discarded -- it is never persisted.
    signature: bytes

    @field_validator("target_id")
    @classmethod
    def _target_id_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "target_id")

    @field_validator("signer_actor_id")
    @classmethod
    def _signer_actor_id_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "signer_actor_id")

    @field_validator("public_key", mode="before")
    @classmethod
    def _public_key_is_32_bytes(cls, v: Any) -> bytes:
        return _decode_base64(v, "public_key", PUBLIC_KEY_LENGTH)

    @field_validator("signature", mode="before")
    @classmethod
    def _signature_is_64_bytes(cls, v: Any) -> bytes:
        return _decode_base64(v, "signature", SIGNATURE_LENGTH)


class AttestationResponse(BaseModel):
    """Public attestation view: no raw signature, only its SHA-256 digest."""

    model_config = ConfigDict(from_attributes=True)

    id: str
    target_type: Literal["claim", "evidence_bundle"]
    target_id: str
    signer_actor_id: str
    #: Base64 of the 32-byte Ed25519 public key.
    public_key: str
    signature_digest_algorithm: str
    signature_digest_hex: str
    #: Always true for stored attestations: only verified rows are written.
    verified: bool
    created_at: datetime


class AttestationListResponse(BaseModel):
    items: list[AttestationResponse]
    count: int

"""Domain errors and their JSON rendering.

Every failure class maps to a stable error code and HTTP status so callers can
distinguish conflicts, unknown references, malformed input, and missing
resources programmatically::

    {"error": {"code": "actor_already_exists", "message": "...", "details": {...}}}
"""

from __future__ import annotations

from fastapi import Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from starlette.exceptions import HTTPException as StarletteHTTPException


class DomainError(Exception):
    """Base class for expected, client-facing domain failures."""

    status_code: int = 400
    code: str = "domain_error"
    message: str = "Request failed."

    def __init__(self, message: str | None = None, details: dict | None = None):
        super().__init__(message or self.message)
        if message is not None:
            self.message = message
        self.details = details or {}

    def to_response(self) -> JSONResponse:
        body: dict = {"code": self.code, "message": self.message}
        if self.details:
            body["details"] = self.details
        return JSONResponse(
            status_code=self.status_code,
            content={"error": body},
        )


class ActorAlreadyExistsError(DomainError):
    status_code = 409
    code = "actor_already_exists"
    message = "An actor with the given identifier already exists."

    def __init__(self, actor_id: str):
        super().__init__(details={"actor_id": actor_id})


class UnknownActorError(DomainError):
    status_code = 404
    code = "unknown_actor"
    message = "The referenced source actor does not exist."

    def __init__(self, actor_id: str):
        super().__init__(details={"actor_id": actor_id})


class ContentNotFoundError(DomainError):
    status_code = 404
    code = "content_not_found"
    message = "The requested content does not exist."

    def __init__(self, content_id: str):
        super().__init__(details={"content_id": content_id})


class ClaimNotFoundError(DomainError):
    status_code = 404
    code = "claim_not_found"
    message = "The requested claim does not exist."

    def __init__(self, claim_id: str):
        super().__init__(details={"claim_id": claim_id})


class EvidenceBundleNotFoundError(DomainError):
    status_code = 404
    code = "evidence_bundle_not_found"
    message = "The requested evidence bundle does not exist."

    def __init__(self, evidence_bundle_id: str):
        super().__init__(details={"evidence_bundle_id": evidence_bundle_id})


class AttestationNotFoundError(DomainError):
    status_code = 404
    code = "attestation_not_found"
    message = "The requested attestation does not exist."

    def __init__(self, attestation_id: str):
        super().__init__(details={"attestation_id": attestation_id})


class ContentRelationNotFoundError(DomainError):
    status_code = 404
    code = "content_relation_not_found"
    message = "The requested content relation does not exist."

    def __init__(self, relation_id: str):
        super().__init__(details={"relation_id": relation_id})


class ContentRelationValidationError(DomainError):
    """A structurally valid relation request that the graph rejects.

    Self-loops and edges that would close a cycle render as the same
    ``validation_error`` code as malformed payloads: both are client input
    the service refuses to persist.
    """

    status_code = 422
    code = "validation_error"
    message = "Request payload failed validation."

    def __init__(self, reason: str):
        super().__init__(details={"reason": reason})


class AttestationVerificationError(DomainError):
    status_code = 422
    code = "attestation_verification_failed"
    message = "The attestation signature could not be verified."

    def __init__(self, details: dict | None = None):
        super().__init__(details=details)


class LineageValidationError(DomainError):
    """A malformed lineage query (``direction`` / ``max_depth``).

    Renders with the same ``validation_error`` code and issue-shaped details
    as request-body validation failures.
    """

    status_code = 422
    code = "validation_error"
    message = "Request payload failed validation."

    def __init__(self, issues: list[dict]):
        super().__init__(details={"issues": issues})


def _validation_body(exc: RequestValidationError) -> dict:
    # Keep the payload small, stable, and JSON-safe: loc/msg/type per error.
    issues = [
        {
            "loc": [str(part) for part in error.get("loc", [])],
            "msg": error.get("msg", ""),
            "type": error.get("type", ""),
        }
        for error in exc.errors()
    ]
    return {
        "error": {
            "code": "validation_error",
            "message": "Request payload failed validation.",
            "details": {"issues": issues},
        }
    }


def register_exception_handlers(app) -> None:
    @app.exception_handler(DomainError)
    async def _handle_domain_error(_: Request, exc: DomainError) -> JSONResponse:
        return exc.to_response()

    @app.exception_handler(RequestValidationError)
    async def _handle_validation_error(
        _: Request, exc: RequestValidationError
    ) -> JSONResponse:
        return JSONResponse(status_code=422, content=_validation_body(exc))

    @app.exception_handler(StarletteHTTPException)
    async def _handle_http_error(
        _: Request, exc: StarletteHTTPException
    ) -> JSONResponse:
        return JSONResponse(
            status_code=exc.status_code,
            content={
                "error": {
                    "code": {
                        404: "not_found",
                        405: "method_not_allowed",
                        409: "conflict",
                    }.get(exc.status_code, "http_error"),
                    "message": str(exc.detail),
                }
            },
        )

    @app.exception_handler(Exception)
    async def _handle_unexpected(_: Request, exc: Exception) -> JSONResponse:
        # Never leak internals (or content-bearing payloads) to clients.
        return JSONResponse(
            status_code=500,
            content={"error": {"code": "internal_error", "message": "Internal error."}},
        )

