def _b64decode(value: str) -> bytes | None:
    # Only the URL-safe alphabet with stripped canonical padding is accepted;
    # validate=True rejects '+', '/', whitespace, and any other character.
    if not value or any(ch in value for ch in "=") or not all(
        ch.isalnum() or ch in "-_" for ch in value
    ):
        return None
    padded = value + "=" * (-len(value) % 4)
    try:
        raw = base64.urlsafe_b64decode(padded.encode("ascii"), validate=True)
    except (ValueError, TypeError):
        return None
    if _b64encode(raw) != value:
        return None
    return raw

